import{_ as t,o,c as d,ag as a}from"./chunks/framework.HG0H2VLS.js";const g=JSON.parse('{"title":"TableCard — Figma Notes","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/components/TableCard/TableCard.figma-notes.md","filePath":"public/demos/src/components/TableCard/TableCard.figma-notes.md"}'),s={name:"public/demos/src/components/TableCard/TableCard.figma-notes.md"};function r(n,e,i,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="tablecard-—-figma-notes" tabindex="-1">TableCard — Figma Notes <a class="header-anchor" href="#tablecard-—-figma-notes" aria-label="Permalink to &quot;TableCard — Figma Notes&quot;">​</a></h1><p><strong>Tier:</strong> Component <strong>Built:</strong> 2026-08-25 (Seating Planner module, wave 3) <strong>Header restructured:</strong> 2026-08-25 — see below <strong>Files:</strong> <code>TableCard.css</code>, <code>TableCard.html</code>, <code>TableCard.figma.ts</code>, <code>TableCard.figma-notes.md</code><strong>Composes:</strong> TableType (<code>.table-type</code>) — tier pill; FullBadge (<code>.full-badge</code>) — at-capacity pill; Button (<code>btn btn--secondary btn--icon btn--2xs</code>) — edit + delete <strong>JS:</strong> none</p><h2 id="figma-node" tabindex="-1">Figma Node <a class="header-anchor" href="#figma-node" aria-label="Permalink to &quot;Figma Node&quot;">​</a></h2><ul><li><strong>File key:</strong> <code>Lus07xi8pPXLN87sQIyrEt</code> (Affino AI — Design System)</li><li><strong>Page:</strong> Seat Planner (<code>3087:5050</code>)</li><li><strong>Component set:</strong> <code>3470:85483</code></li></ul><h2 id="variant-matrix-12-variants" tabindex="-1">Variant matrix (12 variants) <a class="header-anchor" href="#variant-matrix-12-variants" aria-label="Permalink to &quot;Variant matrix (12 variants)&quot;">​</a></h2><p>Axes are <strong>Tier × State × Type × Device</strong>. Tier is single-valued (<code>Component</code>). Device is a media query. <strong>Type produces no CSS at all</strong> — see below. So 12 Figma variants collapse to <strong>one</strong> CSS class plus a media query.</p><table tabindex="0"><thead><tr><th>Type</th><th>State</th><th>Device</th><th>Node</th><th>CSS</th></tr></thead><tbody><tr><td>Empty</td><td>Default</td><td>Desktop</td><td><code>3470:85482</code></td><td><code>.table-card</code></td></tr><tr><td>Empty</td><td>Selected</td><td>Desktop</td><td><code>3470:85481</code></td><td><code>+ .table-card--selected</code></td></tr><tr><td>Populated</td><td>Default</td><td>Desktop</td><td><code>3470:85480</code></td><td><code>.table-card</code></td></tr><tr><td>Populated</td><td>Selected</td><td>Desktop</td><td><code>3470:85479</code></td><td><code>+ .table-card--selected</code></td></tr><tr><td>Full</td><td>Default</td><td>Desktop</td><td><code>3472:85601</code></td><td><code>.table-card</code></td></tr><tr><td>Full</td><td>Selected</td><td>Desktop</td><td><code>3472:85640</code></td><td><code>+ .table-card--selected</code></td></tr><tr><td>Empty</td><td>Default</td><td>Mobile</td><td><code>3484:188877</code></td><td><code>@media (max-width: 767px)</code></td></tr><tr><td>Empty</td><td>Selected</td><td>Mobile</td><td><code>3484:188900</code></td><td>↑ + <code>--selected</code></td></tr><tr><td>Populated</td><td>Default</td><td>Mobile</td><td><code>3484:188923</code></td><td>↑</td></tr><tr><td>Populated</td><td>Selected</td><td>Mobile</td><td><code>3484:189007</code></td><td>↑ + <code>--selected</code></td></tr><tr><td>Full</td><td>Default</td><td>Mobile</td><td><code>3484:188962</code></td><td>↑</td></tr><tr><td>Full</td><td>Selected</td><td>Mobile</td><td><code>3484:189046</code></td><td>↑ + <code>--selected</code></td></tr></tbody></table><p>Desktop: Empty 289×172, Populated/Full 289×185. Mobile: 289×162 / 289×175. (Figma shed 1px when the bar-to-legend gap went 9px → 8px, which the CSS already used.)</p><p>Rendered heights are <strong>177 / 190</strong>, i.e. +5. Three sources: the card&#39;s own 1px border top and bottom; the two rules — Figma draws those as zero-height <code>line</code> nodes with the stroke outside the box, whereas an <code>&lt;hr&gt;</code> with a 1px border is genuinely 1px tall; and 1px on the title row, where a 16px bold line box measures 20px in the browser against Figma&#39;s 19. Cosmetic arithmetic in an auto-height card.</p><h3 id="the-whole-type-axis-is-data-not-css" tabindex="-1">The whole Type axis is data, not CSS <a class="header-anchor" href="#the-whole-type-axis-is-data-not-css" aria-label="Permalink to &quot;The whole Type axis is data, not CSS&quot;">​</a></h3><p>Empty, Populated and Full differ <strong>only</strong> in:</p><ul><li>how many bar segments exist (Empty has one, the others five),</li><li>how many legend rows exist (Empty one, the others two after wrapping),</li><li>whether the FullBadge is present.</li></ul><p>All three are markup the caller supplies. Nothing branches on Type, so there are deliberately <strong>no <code>--empty</code> / <code>--populated</code> / <code>--full</code> modifiers</strong> — empty modifier classes would be dead code. Only State earns CSS. The 13px height difference between Empty and Populated is just the second legend row (11px + the 2px row gap).</p><h3 id="the-bar-in-figma-contradicts-its-own-legend" tabindex="-1">The bar in Figma contradicts its own legend <a class="header-anchor" href="#the-bar-in-figma-contradicts-its-own-legend" aria-label="Permalink to &quot;The bar in Figma contradicts its own legend&quot;">​</a></h3><p>Figma draws the segments at fixed widths — 62 / 31 / 31 / 62 with the empty one <code>flex-1</code> — against a legend reading Attendee 2, VIP 1, Speaker 1, Sponsor 2, Empty 4 of a 10-seat table. Those widths put 6 of 10 seated at <strong>73% of the track</strong>, not 60%. <strong>Never port them.</strong></p><p>Each segment instead carries its seat count in a <code>--seg</code> custom property and divides the track with <code>flex-grow</code> on a zero <code>flex-basis</code>, so the split is exact and the segments always cover the track (which is why the track needs no background of its own — Figma gives it none). Verified: a 2/1/1/2/4 breakdown renders at exactly 20 / 10 / 10 / 20 / 40 %.</p><p>Two further sample-data contradictions in Figma, worth fixing there but not ported:</p><ul><li><strong>Type=Empty</strong> shows <code>Empty (4)</code> beside <code>0 / 10 seated</code>. Should be <code>Empty (10)</code>. The demo uses 10, because shipping a demo that visibly contradicts itself is worse than deviating from broken sample text.</li><li><strong>Type=Full</strong> shows <code>10 / 10 seated</code> and the FULL badge, but keeps Populated&#39;s legend and its grey empty segment. The demo uses a breakdown that actually sums to 10 with nothing empty.</li></ul><h2 id="interaction-model" tabindex="-1">Interaction model <a class="header-anchor" href="#interaction-model" aria-label="Permalink to &quot;Interaction model&quot;">​</a></h2><p>Confirmed with the designer 2026-08-25 — the same contract as RoomCard and AttendeeCard:</p><ul><li><strong>Presentational only.</strong> The parent module owns selection and toggles <code>.table-card--selected</code>. Selecting a table is what opens Table Detail.</li><li><strong>The whole card is the select trigger.</strong> <code>.table-card__select</code> is a real <code>&lt;button&gt;</code> wrapping the table name, with an <code>::after</code> stretched over the card. <code>.table-card__actions</code> is raised on <code>z-index: 1</code> so edit and delete stay independently clickable. Verified by hit-testing: the card&#39;s lower centre resolves to <code>.table-card__select</code>, the edit button&#39;s centre to its own icon. The tier pill needs no raising — it is not interactive, and the overlay is transparent.</li><li><strong>Focus rings the card, not the name</strong>, via <code>.table-card:has(.table-card__select:focus-visible)</code>.</li></ul><h2 id="state-deltas" tabindex="-1">State deltas <a class="header-anchor" href="#state-deltas" aria-label="Permalink to &quot;State deltas&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Background</th><th>Border</th></tr></thead><tbody><tr><td>Default</td><td><code>--ai-surface-primary</code></td><td>1px solid <code>--ai-border-secondary</code></td></tr><tr><td>Selected</td><td><code>--ai-surface-minimal</code></td><td>1px solid <code>--ai-border-brand</code></td></tr></tbody></table><p>Read from the Selected variant&#39;s design context, <strong>not inferred</strong> — <code>get_variable_defs</code> on <code>3470:85479</code> returns <em>both</em> <code>--ai-surface-primary</code> and <code>--ai-surface-minimal</code>, so the variable list alone could not settle which one the card takes.</p><h2 id="device-mobile-deltas" tabindex="-1">Device=Mobile deltas <a class="header-anchor" href="#device-mobile-deltas" aria-label="Permalink to &quot;Device=Mobile deltas&quot;">​</a></h2><p>Two come from Figma (verified against <code>3484:188923</code>); the third is a designer addition.</p><table tabindex="0"><thead><tr><th>Property</th><th>Desktop</th><th>Mobile</th><th>Source</th></tr></thead><tbody><tr><td>card <code>padding</code></td><td><code>--ai-spacing-5</code> (16px)</td><td><code>--ai-spacing-4</code> (12px)</td><td>Figma</td></tr><tr><td>name <code>font-size</code></td><td><code>--ai-font-fixed-sm</code> (16px)</td><td><code>--ai-font-fixed-xs</code> (14px)</td><td>Figma</td></tr><tr><td><code>__sponsor</code> <code>padding-block-start</code></td><td><code>--ai-spacing-2</code> (6px)</td><td><strong><code>--ai-spacing-0-5</code></strong> (2px), both breakpoints</td><td><strong>designer, 2026-09-10</strong> — see the amendment below</td></tr></tbody></table><p>Figma keeps the sponsor row&#39;s 6px padding at both breakpoints; it was tightened to 4px on mobile, where the smaller 14px title leaves the row looking loosely attached to it. Measured: the sponsor row goes 22px → 20px and the header 42px → 38px, with desktop untouched.</p><p>Bar, legend, swatches, badge and buttons are identical between breakpoints. Note the <code>min-inline-size</code> stays <code>--ai-size-4</code> (240px) at both — <strong>unlike RoomCard</strong>, whose min-width steps 280 → 240.</p><h2 id="token-mapping" tabindex="-1">Token mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th><th>Role</th></tr></thead><tbody><tr><td><code>--ai-surface-primary</code> / <code>--ai-surface-minimal</code></td><td><code>background-color</code></td><td>per state</td></tr><tr><td><code>--ai-border-secondary</code> / <code>--ai-border-brand</code></td><td><code>border-color</code></td><td>per state</td></tr><tr><td><code>--ai-border-secondary</code></td><td>the two rules</td><td>resolved via <code>get_variable_defs</code> on <code>3470:85258</code></td></tr><tr><td><code>--ai-radius-lg</code></td><td>card <code>border-radius</code> (16px)</td><td></td></tr><tr><td><code>light/shadow-xxs</code> → <code>--ai-shadow-xxs</code></td><td>card <code>box-shadow</code></td><td></td></tr><tr><td><code>--ai-spacing-5</code> / <code>--ai-spacing-4</code></td><td>card <code>padding</code> desktop / mobile</td><td></td></tr><tr><td><code>--ai-spacing-4</code></td><td>card <code>gap</code> (12px)</td><td></td></tr><tr><td><code>--ai-size-4</code></td><td>card <code>min-inline-size</code> (240px, both breakpoints)</td><td></td></tr><tr><td><code>--ai-spacing-0</code></td><td>title-group <code>gap</code> (0)</td><td></td></tr><tr><td><code>--ai-font-fixed-sm</code> / <code>-xs</code></td><td>table name, desktop / mobile</td><td></td></tr><tr><td><code>--ai-spacing-2</code></td><td>sponsor row <code>gap</code> + <code>padding-block-start</code> (6px)</td><td></td></tr><tr><td><code>--ai-icon-size-sm</code></td><td>sponsor icon (16px)</td><td>via <code>get_variable_defs</code> on <code>3476:106260</code></td></tr><tr><td><code>--ai-icon-contrast</code></td><td>sponsor icon colour</td><td>same fetch</td></tr><tr><td><code>--ai-font-fixed-xxs</code></td><td>sponsor name, seated count (12px)</td><td></td></tr><tr><td><code>--ai-leading-xs</code></td><td>sponsor name <code>line-height</code></td><td></td></tr><tr><td><code>--ai-text-primary</code> / <code>--ai-text-contrast</code> / <code>--ai-text-secondary</code></td><td>name / sponsor + legend / count</td><td></td></tr><tr><td><code>--ai-spacing-3</code></td><td>bar <code>block-size</code> (8px), viz <code>gap</code>, legend <code>column-gap</code>, footer count <code>gap</code></td><td></td></tr><tr><td><code>--ai-spacing-px</code></td><td>bar segment <code>gap</code> (1px)</td><td></td></tr><tr><td><code>--ai-radius-sm</code></td><td>bar <code>border-radius</code> (4px)</td><td></td></tr><tr><td><code>--ai-spacing-0-5</code></td><td>legend <code>row-gap</code> (2px)</td><td></td></tr><tr><td><code>--ai-radius-xs</code></td><td>legend swatch <code>border-radius</code> (2px)</td><td><strong>token added for this build</strong></td></tr><tr><td><code>--sp-attendee</code> / <code>--sp-vip</code> / <code>--sp-speaker</code> / <code>--sp-sponsor</code></td><td>bar segments + legend swatches</td><td></td></tr><tr><td><code>--ai-surface-contrast</code></td><td>empty segment + swatch</td><td></td></tr><tr><td><code>--ai-font-fixed-6xs</code></td><td>legend text (9px)</td><td></td></tr><tr><td><code>--ai-font-bold</code> / <code>-medium</code> / <code>-regular</code></td><td>name / sponsor + count / legend</td><td></td></tr><tr><td><code>--ai-spacing-1</code></td><td>legend-item <code>gap</code>, actions <code>gap</code> (4px)</td><td></td></tr></tbody></table><h2 id="token-gaps-and-decisions" tabindex="-1">Token gaps and decisions <a class="header-anchor" href="#token-gaps-and-decisions" aria-label="Permalink to &quot;Token gaps and decisions&quot;">​</a></h2><p>Resolved with the designer 2026-08-25 rather than invented.</p><table tabindex="0"><thead><tr><th>Figma</th><th>Decision</th></tr></thead><tbody><tr><td><code>--ai-font-fixed-6xs</code> (a <strong>font-size</strong> token) bound as the 9px gap between bar and legend, <strong>and</strong> as the legend&#39;s column gap</td><td><strong>Snapped to <code>--ai-spacing-3</code></strong> (8px). A 1px change that stops a type token driving layout. <strong>Figma has since followed</strong> — the bar-to-legend gap now measures 8px there too.</td></tr><tr><td>legend swatch <code>border-radius: 2px</code>, unbound</td><td><strong>New token <code>--ai-radius-xs</code></strong> (2px), created in Figma by the designer. <code>--ai-radius-sm</code> (4px) would visibly round an 8px square. Re-exported and confirmed 2026-08-25 — <code>VariableID:3534:102610</code> in <code>FigmaTokens/Scale/Scale.tokens.json</code>.</td></tr><tr><td>card <code>width: 289px</code></td><td><strong>Dropped.</strong> The card is fluid and fills its grid cell. 289px has no token; the bound <code>min-width</code> does (<code>--ai-size-4</code>).</td></tr><tr><td>sponsor row <code>height: 22px</code></td><td><strong>Dropped as derivable</strong> — it was exactly the 16px icon plus the 6px <code>padding-top</code>, so the content defines it. Now measures <strong>18px</strong> on desktop after the 2026-09-10 padding change, which is the derivation doing its job rather than a value to chase.</td></tr><tr><td><code>line</code> node stroke, invisible in design context</td><td><strong><code>--ai-border-secondary</code></strong>, resolved by calling <code>get_variable_defs</code> on the node itself (<code>3470:85258</code>). Not a gap — just hidden behind an SVG asset.</td></tr></tbody></table><h2 id="the-header-restructure-2026-08-25" tabindex="-1">The header restructure (2026-08-25) <a class="header-anchor" href="#the-header-restructure-2026-08-25" aria-label="Permalink to &quot;The header restructure (2026-08-25)&quot;">​</a></h2><p>The designer rebuilt <code>Header-Section</code> (<code>3476:106256</code>) so a long sponsor name gets the whole card width, and added the title-to-pill clearance that the first build had flagged as missing.</p><table tabindex="0"><thead><tr><th></th><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>Header-Section</code></td><td><strong>row</strong> — title column beside the pill</td><td><strong>column</strong></td></tr><tr><td><code>Title-Label-Group</code></td><td><strong>column</strong> — title above the sponsor row</td><td><strong>row</strong> — title beside the pill</td></tr><tr><td>tier pill</td><td>sibling of the title group, <code>gap: 0</code></td><td><strong>inside the title row, <code>gap: --ai-spacing-4</code></strong> (12px)</td></tr><tr><td>sponsor row</td><td>nested in the title column, <code>88px</code> wide</td><td><strong>full-width sibling below the title row</strong></td></tr><tr><td>frame name</td><td><code>Paragraph</code></td><td><code>Sponsor</code></td></tr><tr><td>table name</td><td><code>white-space: nowrap</code>, no overflow</td><td><strong>no <code>nowrap</code> — it wraps</strong> ← <em>reversed 2026-09-10, see below</em></td></tr></tbody></table><p>Verified: name 198 + 12px gap + pill 36 = the full 246px content width; the sponsor row measures the same 246; a long title wraps to two 20px lines with the pill holding its width on the first line.</p><p><strong>This retired one of the two divergences the first build carried, and the other has since come back.</strong> The header gap is now Figma&#39;s own 12px rather than something left at 0 and flagged. The table name&#39;s ellipsis was dropped here — Figma dropping <code>nowrap</code> read as wrapping being the intended answer to a long name — <strong>but it was restored on 2026-09-10 at the designer&#39;s request; see &quot;The table name truncates to one line&quot; below.</strong> <code>flex-shrink: 0</code> on the pill is scoped from this row (Figma sets <code>shrink-0</code> on the instance); nothing about TableType&#39;s own appearance is touched.</p><blockquote><p><strong>Only 1 of 12 Figma variants carries this.</strong> <code>3470:85480</code> — the Populated / Default / Desktop variant — is restructured. <code>3470:85479</code>, <code>3472:85601</code> and <code>3484:188923</code> were all checked and still have the old nested header, so the other eleven need the same change in Figma. The CSS applies it to every variant, since it is one shared header.</p></blockquote><h2 id="two-places-the-css-leads-figma" tabindex="-1">Two places the CSS leads Figma <a class="header-anchor" href="#two-places-the-css-leads-figma" aria-label="Permalink to &quot;Two places the CSS leads Figma&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Property</th><th>Figma</th><th>CSS</th></tr></thead><tbody><tr><td><code>__sponsor-name</code></td><td>truncation</td><td><code>white-space: nowrap</code> + <code>shrink-0</code></td><td><strong>+ <code>overflow: hidden</code>, <code>text-overflow: ellipsis</code></strong></td></tr><tr><td><code>__legend-item</code></td><td><code>font-weight</code></td><td><code>--ai-font-regular</code></td><td><strong><code>--ai-font-medium</code></strong></td></tr></tbody></table><p><strong>The sponsor name needs somewhere to stop.</strong> Figma pairs <code>nowrap</code> with <code>shrink-0</code>, which overflows rather than truncating. The full-width row gives a long name far more room than before, but it still needs a limit — verified truncating at 246px.</p><p><strong>The legend is medium</strong>, a designer call 2026-08-25 — at 9px, regular sits too light against the surrounding text. No layout consequence: the legend still measures 24px across two rows and no card height moved.</p><h2 id="a-figma-property-inconsistency-worth-fixing" tabindex="-1">A Figma property inconsistency worth fixing <a class="header-anchor" href="#a-figma-property-inconsistency-worth-fixing" aria-label="Permalink to &quot;A Figma property inconsistency worth fixing&quot;">​</a></h2><p>The three variants expose three different property sets for what is one component:</p><table tabindex="0"><thead><tr><th>Variant</th><th>Properties</th></tr></thead><tbody><tr><td>Populated / Default / Desktop (<code>3470:85480</code>)</td><td><code>Show Sponsor</code> only — and it gates <strong>both</strong> the sponsor row <strong>and</strong> the tier pill</td></tr><tr><td>Populated / Selected / Desktop (<code>3470:85479</code>)</td><td><code>Show Sponsor</code>, <code>Show Table Type</code>, <code>Table Name</code>, plus a <code>Table Type</code> slot</td></tr><tr><td>Populated / Default / Mobile (<code>3484:188923</code>)</td><td><code>Show Sponsor</code>, <code>Table Name</code></td></tr></tbody></table><p>The Default variant tying the tier pill to <code>Show Sponsor</code> is almost certainly an error — a table with no sponsor should still show its tier. The Selected variant models it correctly with a separate <code>Show Table Type</code>. <strong>Built the correct model</strong>: the sponsor row and the tier pill are independently optional. <code>Table Name</code> also exists on some variants and not others, which is why <code>TableCard.figma.ts</code> does <strong>not</strong> use <code>figma.string</code> for it — binding a property that only some variants carry is how the TableType Code Connect went wrong in wave 1.</p><h2 id="cross-component-findings" tabindex="-1">Cross-component findings <a class="header-anchor" href="#cross-component-findings" aria-label="Permalink to &quot;Cross-component findings&quot;">​</a></h2><ul><li><strong>TableType is unchanged, by decision — and the size drift has since closed.</strong> When first built, Figma&#39;s instance rendered at <code>--ai-font-fixed-6xs</code> (9px); as of the header restructure it reads <code>--ai-font-fixed-5xs</code> (10px), matching the component, and the pill grew 34×17 → 36×18 accordingly. Only <code>--ai-tracking-6</code> vs the component&#39;s <code>--ai-tracking-7</code>, and <code>font-semibold</code> vs <code>--ai-font-bold</code>, still differ — the two amends the designer made in wave 1. The call 2026-08-25 was that <strong>the component is the source of truth</strong> and Figma should follow, so nothing was changed. Its colour model was verified correct in passing: Figma&#39;s <code>#b2d5e2</code> border, <code>#005777</code> text and white-80%-over-<code>#00749e</code> fill are exactly what TableType&#39;s three <code>color-mix()</code> formulas produce.</li><li><strong><code>--sp-host</code> is missing from Figma&#39;s legend.</strong> The collection defines it and AttendeeCard uses it, but Table Card&#39;s Figma legend covers only Attendee / VIP / Speaker / Sponsor plus Empty. <strong>Not added here</strong> — inventing a variant with no Figma counterpart is how drift starts. But a table seating a host currently has no colour for them. Since the colour comes from one custom property, adding <code>--host</code> later is a single line. <strong>Worth a designer decision.</strong></li><li><strong>FullBadge was extracted</strong> rather than scoped a second time, because TableCard draws a copy identical to RoomCard&#39;s. See <code>FullBadge.figma-notes.md</code> — including that Figma still has no component for it.</li></ul><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><ul><li><strong>The bar is <code>aria-hidden</code>.</strong> The legend states every role and count as text immediately below it, and the footer states the total — a bare stack of coloured divs adds nothing but noise.</li><li><strong>The action buttons are 24×24</strong>, under the 44×44 minimum in CLAUDE.md §9. Built as drawn, matching the AttendeeCard and RoomCard decisions. The card&#39;s own select target is the full card.</li><li>The FullBadge&#39;s white-on-success contrast (3.16:1) is deliberately open — see its notes.</li><li>The table name is an <code>&lt;h3&gt;</code>; the demo nests it under <code>&lt;h2&gt;</code> section headings.</li></ul><h2 id="where-radius-tokens-actually-live" tabindex="-1">Where radius tokens actually live <a class="header-anchor" href="#where-radius-tokens-actually-live" aria-label="Permalink to &quot;Where radius tokens actually live&quot;">​</a></h2><p>Worth recording, because it cost a wrong guess: the Style Dictionary build reads <code>FigmaTokens/Scale/Scale.tokens.json</code> and <code>FigmaTokens/Semantic/*</code>. The <strong>top-level</strong><code>FigmaTokens/Light.tokens.json</code>, <code>Dark.tokens.json</code> and <code>Primitive.tokens.json</code> are <em>not</em> build sources, despite also containing radius entries — they are legacy files. <code>--ai-radius-xs</code> was briefly hand-added to all three; only the Scale one had any effect, and removing the other two left <code>css/tokens.css</code> byte-identical. <strong>Radius comes from Scale alone.</strong></p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong><code>get_design_context</code> returns the actions frame as an empty <code>&lt;div&gt;</code></strong> on every variant — the two Button instances are flattened out. Only <code>get_metadata</code> on the frame reveals them. The same happened on RoomCard; don&#39;t read that empty div as &quot;no actions&quot;.</li><li><strong>Design context under-reports bound tokens.</strong> The seated count renders as raw <code>text-[12px]</code> and the min-width as <code>min-w-[240px]</code>, but <code>get_variable_defs</code> shows both bound. Always cross-check before flagging a gap.</li><li><strong>The bar segments are named <code>Bar-Staff</code> and <code>Bar-Guest</code></strong> in Figma while the legend beside them says &quot;Attendee&quot; and &quot;Sponsor&quot;. The legend text is what users see, so the CSS uses <code>--attendee</code> and <code>--sponsor</code>. Worth renaming the Figma layers.</li><li><strong>No hover, focus, pressed or disabled variants</strong> exist in the set. The action buttons get Button&#39;s own states; nothing else was invented.</li><li><strong>No dark-mode variant.</strong> Every colour is a theme-aware <code>--ai-*</code> token except the <code>--sp-*</code> role colours, which are <strong>not</strong> theme-aware — so the bar and legend will not adapt under <code>[data-theme=&quot;dark&quot;]</code>. Not designed or reviewed.</li></ul><hr><h2 id="responsive-container-queries-2026-08-27" tabindex="-1">Responsive: container queries (2026-08-27) <a class="header-anchor" href="#responsive-container-queries-2026-08-27" aria-label="Permalink to &quot;Responsive: container queries (2026-08-27)&quot;">​</a></h2><p><strong>Keys on <code>cs-page</code>, NOT a self-container.</strong> Measured own width <strong>275px</strong> on desktop and ~300px on mobile — both under 767, so a self-query would fire on desktop too and the card would permanently wear its mobile padding. The Device=Mobile deltas describe the screen, not the card.</p><p>Rationale and the decision rule live in <strong>CLAUDE.md §4a</strong>. The short version: a docked SidebarMenu shrinks the CC content column with no window resize, so a viewport query cannot see the real available width — measured 820px of column at a 2239px viewport, with no query firing.</p><h2 id="the-visualisation-block-absorbs-extra-card-height-designer-2026-09-10" tabindex="-1">The visualisation block absorbs extra card height (designer, 2026-09-10) <a class="header-anchor" href="#the-visualisation-block-absorbs-extra-card-height-designer-2026-09-10" aria-label="Permalink to &quot;The visualisation block absorbs extra card height (designer, 2026-09-10)&quot;">​</a></h2><p>TableListing now stretches every card on a row to the tallest one (its notes carry the reasoning and the Figma geometry). That raises a question this component has to answer: when a card is taller than its content, <strong>where does the slack go?</strong></p><p>Figma&#39;s listing instances answer it — <code>lRKvtYSU3SvO5hbMT33jxw</code> <code>1:31485</code>. The seated-count row sits a constant 16px, the card&#39;s own padding, from the bottom edge in all three row tracks:</p><table tabindex="0"><thead><tr><th>Row track</th><th>Footer y</th><th>Footer + 24 + 16</th><th><code>Visualization-Slot</code></th><th>Its content</th></tr></thead><tbody><tr><td>186</td><td>146</td><td>186</td><td>41</td><td>28</td></tr><tr><td>164</td><td>124</td><td>164</td><td>41</td><td>27</td></tr><tr><td>150</td><td>110</td><td>150</td><td>27</td><td>27 (natural)</td></tr></tbody></table><p>So the footer is pinned to the bottom and the bar/legend block grows — not the other way round, and not slack left below the footer. Implemented as <code>flex: 1 1 auto</code> on <code>.table-card__viz</code>, which is a no-op on an unstretched card because there is no slack to take.</p><p>The slack lands <strong>after</strong> the legend rather than around it. Figma&#39;s two row-1 instances disagree here — <code>1:31319</code> centres its bar+legend in the grown slot at y=6.5 while <code>1:31336</code> tops it at y=0 — and the designer settled it start-aligned, which is the default <code>justify-content</code> on that column, so no declaration is needed.</p><p>Nothing about the card&#39;s own drawn variants changed: at their natural heights every measurement is as before.</p><h2 id="sponsor-row-padding-2px-on-desktop-designer-2026-09-10" tabindex="-1">Sponsor row padding: 2px on desktop (designer, 2026-09-10) <a class="header-anchor" href="#sponsor-row-padding-2px-on-desktop-designer-2026-09-10" aria-label="Permalink to &quot;Sponsor row padding: 2px on desktop (designer, 2026-09-10)&quot;">​</a></h2><p><code>.table-card__sponsor</code> takes <strong><code>padding-block-start: var(--ai-spacing-0-5)</code></strong> (2px). Figma binds <code>--ai-spacing-2</code> (6px) — confirmed on the sponsor row&#39;s own variable defs (<code>3476:106259</code>) rather than inferred. A deliberate divergence; <strong>Figma wants updating.</strong></p><p>The <code>gap</code> is untouched at <code>--ai-spacing-2</code>. Figma binds the same token to both, but only the padding was asked about and the two do different jobs: one sets the row&#39;s distance from the title, the other the icon&#39;s distance from the name.</p><p>Knock-on effects, all of which resolve themselves because they were built as derivations rather than pinned numbers:</p><table tabindex="0"><thead><tr><th></th><th>Before</th><th>After</th></tr></thead><tbody><tr><td>Sponsor row height</td><td>22px</td><td><strong>18px</strong></td></tr><tr><td>Header height (sponsored card)</td><td>42px</td><td><strong>38px</strong></td></tr></tbody></table><p>The Seating Planner&#39;s per-row header alignment measures headers rather than assuming 42, so it adapted with no change — row 1 went from <code>42/42/42/42</code> to <code>38/38/38/38</code> with bars and legends still aligned. Verified. TableDetail&#39;s notes cross-reference &quot;the identical 22px&quot; in TableCard; that sentence is now historical, and its own sponsor row is unaffected.</p><h3 id="the-mobile-override-is-gone-so-both-breakpoints-are-2px" tabindex="-1">The mobile override is gone, so both breakpoints are 2px <a class="header-anchor" href="#the-mobile-override-is-gone-so-both-breakpoints-are-2px" aria-label="Permalink to &quot;The mobile override is gone, so both breakpoints are 2px&quot;">​</a></h3><p>There had been a narrow override of <code>--ai-spacing-1</code> (4px), added 2026-08-25 because <em>&quot;the smaller 14px title leaves the sponsor row looking loosely attached to it&quot;</em>. Once desktop moved to 2px that made <strong>mobile looser than desktop</strong> — the reverse of its own purpose — so it was flagged and then dropped at the designer&#39;s request the same day.</p><p><strong>One value now, at every width: 2px.</strong> Figma keeps <code>--ai-spacing-2</code> (6px) at both and wants updating.</p><p>Left as a comment in the block rather than silently deleted, because the mobile value was a deliberate designer call once and a bare absence invites someone to &quot;restore&quot; it.</p><p>(That block is <code>@container cs-page (max-width: 767px)</code>, not the <code>@media</code> the previous version of this note called it — per CLAUDE.md §4a the card keys on the page container, since a docked SidebarMenu narrows the column with no window resize at all.)</p><p>Verified with the demo establishing <code>cs-page</code> itself — a standalone demo has no shell, so the narrow rules can otherwise never fire: 2px padding and an 18px row at both a 900px and a 400px container, with the name still stepping 16px → 14px, which confirms the container block still fires and only the sponsor rule left it.</p><h2 id="the-table-name-truncates-to-one-line-designer-2026-09-10" tabindex="-1">The table name truncates to one line (designer, 2026-09-10) <a class="header-anchor" href="#the-table-name-truncates-to-one-line-designer-2026-09-10" aria-label="Permalink to &quot;The table name truncates to one line (designer, 2026-09-10)&quot;">​</a></h2><p><code>.table-card__select</code> carries <code>white-space: nowrap; overflow: hidden; text-overflow: ellipsis</code>, so a long table name clips to a single line.</p><p><strong>This reverses the 2026-08-25 position, and that one was Figma-derived</strong> — which is exactly why it is worth spelling out rather than quietly re-editing the table above. Figma dropped the <code>nowrap</code> the name used to carry when the header was restructured, so wrapping was read as the intended answer to a long name and the earlier ellipsis was retired as a divergence. In practice a real name did what the restructure was supposed to accommodate and looked wrong doing it: &quot;Headline Sponsors testing long&quot; took the title onto two lines and pushed the card taller than its row-mates. So the ellipsis is back, and <strong>Figma is again the side that wants updating.</strong></p><h3 id="it-goes-on-the-button-not-the-heading" tabindex="-1">It goes on the button, not the heading <a class="header-anchor" href="#it-goes-on-the-button-not-the-heading" aria-label="Permalink to &quot;It goes on the button, not the heading&quot;">​</a></h3><p><code>__name</code> is the flex item but <code>__select</code> is the block that actually contains the text, so the truncation has to live on the button. Three things already in place make it work, and all three are needed:</p><table tabindex="0"><thead><tr><th>On</th><th>Property</th><th>Why it matters here</th></tr></thead><tbody><tr><td><code>__select</code></td><td><code>display: block</code></td><td><code>text-overflow</code> does nothing on an inline box</td></tr><tr><td><code>__select</code></td><td><code>max-inline-size: 100%</code></td><td>gives it a width to clip against</td></tr><tr><td><code>__name</code></td><td><code>min-inline-size: 0</code></td><td>lets the flex item shrink below its content instead of pushing the tier chip out of the row</td></tr></tbody></table><p><strong>Verified</strong> with the reported name: <code>nowrap</code> / <code>ellipsis</code> / <code>overflow: hidden</code> computed, button height 20px (one line) on every card, <code>scrollWidth &gt; clientWidth</code> on the long names and not on the short ones, and the tier chip still sharing the name&#39;s row (<code>chipTop: 0</code>) rather than being pushed below. Checked with a chip and without one.</p><p>The sponsor name below it was already truncating — that divergence is separate, older, and unaffected.</p><h2 id="drop-target-reuses-the-selected-styling-designer-2026-09-10" tabindex="-1"><code>--drop-target</code> reuses the Selected styling (designer, 2026-09-10) <a class="header-anchor" href="#drop-target-reuses-the-selected-styling-designer-2026-09-10" aria-label="Permalink to &quot;`--drop-target` reuses the Selected styling (designer, 2026-09-10)&quot;">​</a></h2><p><em>&quot;When an attendee is dragged over a table card, can we use the selected state styling to indicate drop target?&quot;</em></p><p><code>.table-card--drop-target</code> <strong>shares the <code>--selected</code> rule</strong> rather than copying its declarations, so the two cannot drift apart:</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.table-card--selected</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.table-card--drop-target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">border-color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: …border-brand; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">background-color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: …surface-minimal; }</span></span></code></pre></div><p><strong>A separate class, not <code>--selected</code> itself</strong>, and that distinction is the point. The selected table is a persistent choice that drives the detail rail and carries <code>aria-pressed=&quot;true&quot;</code>; a drop target is momentary and carries no such meaning. Reusing the class would make the two indistinguishable in the DOM and would put <code>aria-pressed</code> on a card nobody has pressed. Verified: the drop target computes the same border and background as the selected card, does <strong>not</strong> carry <code>--selected</code>, and keeps <code>aria-pressed=&quot;false&quot;</code>.</p><h3 id="this-closes-a-real-gap-and-it-is-not-a-new-variant" tabindex="-1">This closes a real gap, and it is not a new variant <a class="header-anchor" href="#this-closes-a-real-gap-and-it-is-not-a-new-variant" aria-label="Permalink to &quot;This closes a real gap, and it is not a new variant&quot;">​</a></h3><p><code>seating-drag-unspecified-visuals</code> recorded that a table card would accept a drop and <strong>show nothing at all</strong>. Figma has no drag state for TableCard — 12 variants, not one of them a drag — and an earlier attempt at inventing <code>--drop-legal</code> / <code>--drop-full</code> was removed for exactly that reason: <em>&quot;inventing a variant with no Figma counterpart is how drift starts.&quot;</em></p><p>Pointing at an existing variant&#39;s styling is the designer resolving the gap, not a new variant appearing. Nothing was added to the variant matrix.</p><h3 id="legality-gates-it-the-same-as-the-seat-rows" tabindex="-1">Legality gates it, the same as the seat rows <a class="header-anchor" href="#legality-gates-it-the-same-as-the-seat-rows" aria-label="Permalink to &quot;Legality gates it, the same as the seat rows&quot;">​</a></h3><p>Only the card <strong>under the pointer</strong> is marked, and only when the drop would actually succeed. <code>tableDrop()</code> returns <code>&#39;full&#39;</code> for a table with no free seat — truthy, but <code>place()</code> refuses it with a toast and keeps the pick — so <code>&#39;full&#39;</code> is excluded explicitly. Marking it would promise a drop that is then refused, which is the rule AttendeeCard&#39;s <code>--dragged-over</code> already follows.</p><p>Verified: nothing marked with no pick; the empty Table 6 marks; the full Table 3 does <strong>not</strong>; moving to another card moves the mark rather than adding a second; hovering a seat row clears the card mark; Escape clears everything.</p>',98)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
